<script setup>
import {ref} from 'vue';import {api,session} from '../lib/api.js';import Icon from '../components/Icon.vue';
const email=ref(''),password=ref(''),token=ref(''),recovery=ref(''),useRecovery=ref(false),needCode=ref(false),busy=ref(false),error=ref('');
// Garde anti double-soumission (Entrée répétée / double clic) : une seule requête de connexion à la fois.
async function login(){if(busy.value)return;error.value='';busy.value=true;try{const r=await api('/auth/login',{method:'POST',body:{email:email.value,password:password.value,...(useRecovery.value?{recoveryCode:recovery.value||undefined}:{token:token.value||undefined})}});if(r.twoFactor){needCode.value=true;error.value=r.error||'';return;}Object.assign(session,r);}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><main class="login-page"><section class="login-art"><a class="brand" href="/"><span class="brand-mark">b<span>w</span></span>birostweb<span class="accent">.</span></a><div class="login-statement"><span class="eyebrow">[ ESPACE PRIVÉ / STUDIO INDÉPENDANT ]</span><h1>LES IDÉES.<br>LES PROJETS.<br><span>LA SUITE.</span></h1><div class="login-rule"></div><p>Tout votre studio.<br>Un seul point de vue.</p></div><footer><span class="slash-mark">///</span><span class="eyebrow">DESIGN. CODE. BUSINESS.</span></footer></section><section class="login-form"><span class="eyebrow">01 / CONNEXION</span><h2>De retour<br>au studio<span class="accent">.</span></h2><p>Connectez-vous à votre espace Birostweb.</p><form @submit.prevent="login"><label>Adresse email<input v-model="email" type="email" placeholder="vous@birostweb.fr" autocomplete="username" required autofocus></label><label>Mot de passe<input v-model="password" type="password" placeholder="Votre mot de passe" autocomplete="current-password" required></label><template v-if="needCode"><label v-if="!useRecovery">Code de vérification<input v-model="token" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="6 chiffres de votre application" required autofocus></label><label v-else>Code de secours<input v-model="recovery" autocomplete="off" maxlength="16" placeholder="XXXXX-XXXXX" required autofocus></label><button class="text-button" type="button" @click="useRecovery=!useRecovery">{{useRecovery?'Utiliser le code de l’application':'Application indisponible ? Utiliser un code de secours'}}</button></template><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary full" :disabled="busy">{{busy?'Connexion…':needCode?'Vérifier le code':'Entrer dans le studio'}}<Icon name="ArrowUpRight"/></button></form><div class="login-secure"><Icon name="ShieldCheck" :size="16"/> Espace privé · Accès administrateur</div><nav class="legal-links" aria-label="Informations légales"><a href="https://birostweb.fr/mentions-legales.html" target="_blank" rel="noopener">Mentions légales</a><RouterLink to="/confidentialite">Confidentialité du studio</RouterLink></nav></section></main></template>
